from pathlib import Path
import runpy
import unittest


class InventoryTests(unittest.TestCase):
    def test_positive_quantities(self):
        app = runpy.run_path(str(Path(__file__).resolve().parents[1] / "src/app.py"))
        self.assertEqual(app["stock_total"]([{"quantity": 2}, {"quantity": 4}]), 6)

    def test_empty_inventory(self):
        app = runpy.run_path(str(Path(__file__).resolve().parents[1] / "src/app.py"))
        self.assertEqual(app["stock_total"]([]), 0)

